const zestawIkonyOsiagniecia = {
    Podroznik,
	Instrybutor,
	Dostawca,
	Drwal,
	Ekolog,
	Gabaryciarz,
	JakZJajkiem,
	Laweciarz,
	LowRider,
	LuznyTowar,
	Mrozonka,
	NiebezpiecznyFracht,
	Paleciarz,
	Perfekcjonista,
	PilnyKierowca,
	Polityk,
	PracownikMiesiaca,
	Puszkarz,
	Rzeznik,
	Tanker,
	Wystawca,
	ZaangazowanyPrzewoznik,
	Zarobas,
	ETSOsiagniecie,
	ATSOsiagniecie,
	StaryCzlowiekIMorze
};

const IkonyOsiagniecia = (props) => {
	let tmpClass = props.className || "";
	let czyMa = 0;
	if(props.style){
		if(props.style.width && props.style.height) czyMa = 1;
	}
	if(props.className){
		if(props.className.includes("w-full") && props.className.includes("h-full")) czyMa = 1;
	}
	if(!czyMa){
		tmpClass = tmpClass + " w-full h-full";
	}
	tmpClass = { className: tmpClass };
	
    const Komponent = zestawIkonyOsiagniecia[props.nazwa];
    if(Komponent) return <Komponent {...props} {...tmpClass } />
    else {
		tmpClass.className += " p-2";
		return <BsQuestionDiamondFill {...props} {...tmpClass} />;
	}
};
export default IkonyOsiagniecia;